BEGIN
INSERT INTO TB_PRODUCT_CONDITION( min_age, max_age, foreigner_available_yn, overseas_tax_yn, gender, customer_type, tax_benefit_yn, non_taxable_savings_yn, depositor_protection_yn, min_join_amount, max_join_amount, deposit_unit, min_term_months, max_term_months, term_unit_type, term_unit_value, fixed_term_yn, fixed_term_values, condition_note) VALUES( #{min_age, jdbcType=NUMERIC}, #{max_age, jdbcType=NUMERIC}, #{foreigner_available_yn}, #{overseas_tax_yn}, #{gender, jdbcType=VARCHAR}, #{customer_type, jdbcType=VARCHAR}, #{tax_benefit_yn}, #{non_taxable_savings_yn}, #{depositor_protection_yn}, #{min_join_amount, jdbcType=NUMERIC}, #{max_join_amount, jdbcType=NUMERIC}, #{deposit_unit, jdbcType=NUMERIC}, #{min_term_months, jdbcType=NUMERIC}, #{max_term_months, jdbcType=NUMERIC}, #{term_unit_type}, #{term_unit_value, jdbcType=NUMERIC}, #{fixed_term_yn}, #{fixed_term_values, jdbcType=VARCHAR}, #{condition_note, jdbcType=VARCHAR}) RETURNING condition_no INTO #{condition_no, mode=OUT, jdbcType=NUMERIC};
END;
